diff --git a/debian/patches/db-update-snapd-bad-request.patch b/debian/patches/db-update-snapd-bad-request.patch
new file mode 100644
index 0000000..ebb0ae0
--- /dev/null
+++ b/debian/patches/db-update-snapd-bad-request.patch
@@ -0,0 +1,95 @@
+Description: Change firmware update format to align with snapd
+ Send composite firmware updates as signature lists as expected
+ by snapd.
+Author: Valentin David <valentin.david@canonical.com>
+
+---
+Bug: https://github.com/fwupd/fwupd/pull/9870
+Bug-Ubuntu: https://launchpad.net/bugs/2139611
+Forwarded: https://github.com/fwupd/fwupd/commit/703e2fd69efdbe95d601175ca9b948f47eada1f4
+Applied-Upstream: https://github.com/fwupd/fwupd/commit/703e2fd69efdbe95d601175ca9b948f47eada1f4
+Reviewed-By: Simon Johnsson <simon.johnsson@canonical.com>
+Last-Update: 2026-02-05
+
+--- fwupd-2.0.19.orig/plugins/snapd-uefi/fu-snapd-uefi-plugin.c
++++ fwupd-2.0.19/plugins/snapd-uefi/fu-snapd-uefi-plugin.c
+@@ -248,28 +248,65 @@ fu_snapd_uefi_plugin_composite_peek_firm
+ 	gsize bufsz = 0;
+ 	const gchar *key_database;
+ 	const guint8 *buf;
+-	g_autofree gchar *b64data = NULL;
+ 	g_autofree gchar *msg = NULL;
+-	g_autoptr(GBytes) fw = NULL;
++	g_autoptr(GPtrArray) images = NULL;
+ 
+ 	/* not interesting */
+ 	key_database = fu_snapd_uefi_plugin_device_to_key_database(self, device);
+ 	if (key_database == NULL)
+ 		return TRUE;
+ 
+-	/* get default image */
+-	fw = fu_firmware_get_bytes(firmware, error);
+-	if (fw == NULL)
++	images = fu_firmware_get_images(firmware);
++	if (images->len == 1) {
++		g_autoptr(GBytes) fw = NULL;
++		g_autofree gchar *b64data = NULL;
++		/* get default image */
++		fw = fu_firmware_get_bytes(firmware, error);
++		if (fw == NULL)
++			return FALSE;
++		buf = g_bytes_get_data(fw, &bufsz);
++		b64data = g_base64_encode(buf, bufsz);
++		msg = g_strdup_printf("{"
++				      "\"action\":\"efi-secureboot-update-db-prepare\","
++				      "\"key-database\":\"%s\","
++				      "\"payload\":\"%s\""
++				      "}",
++				      key_database,
++				      b64data);
++	} else if (images->len > 1) {
++		g_autofree gchar *payloads_msg = NULL;
++
++		for (guint i = 0; i < images->len; i++) {
++			g_autofree gchar *b64data = NULL;
++				g_autoptr(GBytes) fw = NULL;
++				FuFirmware *image = g_ptr_array_index(images, i);
++				fw = fu_firmware_get_bytes(image, error);
++				if (fw == NULL)
++					return FALSE;
++				buf = g_bytes_get_data(fw, &bufsz);
++				b64data = g_base64_encode(buf, bufsz);
++				if (i == 0) {
++					payloads_msg = g_strdup_printf("\"%s\"", b64data);
++				} else {
++					g_autofree gchar *previous_payloads_msg = payloads_msg;
++					payloads_msg = NULL;
++					payloads_msg = g_strdup_printf("%s,\"%s\"", previous_payloads_msg, b64data);
++				}
++		}
++		msg = g_strdup_printf("{"
++				      "\"action\":\"efi-secureboot-update-db-prepare\","
++				      "\"key-database\":\"%s\","
++				      "\"payloads\":[%s]"
++				      "}",
++				      key_database,
++				      payloads_msg);
++	} else {
++		g_set_error(error,
++			    FWUPD_ERROR,
++			    FWUPD_ERROR_INTERNAL,
++			    "no images in firmware");
+ 		return FALSE;
+-	buf = g_bytes_get_data(fw, &bufsz);
+-	b64data = g_base64_encode(buf, bufsz);
+-	msg = g_strdup_printf("{"
+-			      "\"action\":\"efi-secureboot-update-db-prepare\","
+-			      "\"key-database\":\"%s\","
+-			      "\"payload\":\"%s\""
+-			      "}",
+-			      key_database,
+-			      b64data);
++	}
+ 
+ 	/* Notify of an upcoming update to the DBX. A successful call shall initiate a
+ 	 * change tracking an update to the DBX on the snapd side */
